import { formatCurrency, ICurrencySettings } from '@game-studio/utilities';
import { ISessionStatus, ISessionStatusBar } from '../../types';
import { Component, Prop, Vue } from 'vue-property-decorator';

@Component({})
export default class SessionStatusBarComponent extends Vue {
    @Prop()
    public readonly session: ISessionStatus;

    @Prop()
    public readonly translations: ISessionStatusBar;

    @Prop()
    public readonly currencyConfig: ICurrencySettings;

    get currentBet(): string {
        return this.stringifyBet(this.session.CurrentBet);
    }

    get totalWinnings(): string {
        return this.stringifyBet(this.session.TotalWinnings);
    }

    get netBalance(): string {
        return this.stringifyBet(this.session.NetBalance);
    }

    private stringifyBet(bet: number): string {
        const currencyConfig = this.currencyConfig;
        return formatCurrency(bet, currencyConfig, false);
    }
}